cat > catalog.py <<'EOF'
import json
import sys
from pathlib import Path


def search_key(title):
    return title.casefold()


def load(path="data/books.json"):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def build_export(rows):
    """Return the search export; every edition is kept, inactive ones flagged.

    Rows are ordered by key then identity so the artifact is reproducible
    regardless of the import order of the source file.
    """
    books = [
        {
            "isbn": row["isbn"],
            "edition": row["edition"],
            "title": row["title"],
            "active": row["active"],
            "key": search_key(row["title"]),
        }
        for row in rows
    ]
    books.sort(key=lambda book: (book["key"], book["isbn"], book["edition"]))
    return {"books": books}


def write_export(export, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(export, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def prefix_search(export, prefix):
    """Match the folded prefix against the key, never against the title."""
    folded_prefix = search_key(prefix)
    return [book for book in export["books"] if book["key"].startswith(folded_prefix)]


def print_inventory():
    rows = load()
    print(json.dumps({"rows": len(rows), "unique_isbns": len({r["isbn"] for r in rows}),
                      "keys": [search_key(r["title"]) for r in rows]}, ensure_ascii=False))


USAGE = "usage: python catalog.py [export [PATH] | search PREFIX]"


def main(argv):
    if not argv:
        print_inventory()
    elif argv[0] == "export" and len(argv) <= 2:
        write_export(build_export(load()), argv[1] if len(argv) == 2 else "build/search.json")
    elif argv[0] == "search" and len(argv) == 2:
        for book in prefix_search(build_export(load()), argv[1]):
            print(json.dumps(book, ensure_ascii=False))
    else:
        raise SystemExit(USAGE)


if __name__ == "__main__":
    main(sys.argv[1:])
EOF
cat >> tests/test_catalog.py <<'EOF'


def test_key_can_be_longer_than_title():
    book = next(b for b in build_export(load())["books"] if b["title"] == "Straße Atlas")
    assert len(book["key"]) > len(book["title"])


def test_export_keeps_every_edition_and_original_title():
    books = build_export(load())["books"]
    assert {(b["isbn"], b["edition"]) for b in books} == {(r["isbn"], r["edition"]) for r in load()}
    assert "Straße Atlas" in {b["title"] for b in books}


def test_export_order_ignores_storage_order():
    rows = load()
    assert build_export(rows) == build_export(list(reversed(rows)))


def test_prefix_search_uses_folded_key():
    export = build_export(load())
    assert [b["edition"] for b in prefix_search(export, "STRASSE")] == ["large-print", "paper"]
    assert [b["title"] for b in prefix_search(export, "APP")] == ["apple Almanac"]
    assert prefix_search(export, "Straße A") != []
    assert prefix_search(export, "nothing") == []


def test_write_export_round_trips_unicode(tmp_path):
    export = build_export(load())
    target = tmp_path / "nested" / "search.json"
    write_export(export, target)
    assert json.loads(target.read_text(encoding="utf-8")) == export
